236	  // =========================================================================
237	  // Private: 机会与风险
238	  // =========================================================================
239	
240	  private buildRiskOpportunitySection(report: DailyReport): string {
241	    const { risk_opportunity: riskOpp } = report;
242	    const lines: string[] = ['## 机会与风险提示'];
243	
244	    // 风险
245	    if (riskOpp.risks.length > 0) {
246	      lines.push('');
247	      lines.push('### 风险');
248	      for (const risk of riskOpp.risks) {
249	        const levelLabel = this.getRiskLevelLabel(risk.level);
250	        const relatedStr = risk.related_items.length > 0
251	          ? ` [ref: ${risk.related_items.join(', ')}]`
252	          : '';
253	        lines.push(`- [${levelLabel}] ${risk.description} (概率: ${risk.probability}) → ${risk.suggested_action}${relatedStr}`);
254	      }
255	    } else {
256	      lines.push('');
257	      lines.push('### 风险');
258	      lines.push('暂无显著风险。');
259	    }
260	
261	    // 机会
262	    if (riskOpp.opportunities.length > 0) {
263	      lines.push('');
264	      lines.push('### 机会');
265	      for (const opp of riskOpp.opportunities) {
266	        const relatedStr = opp.related_items.length > 0
267	          ? ` [ref: ${opp.related_items.join(', ')}]`
268	          : '';
269	        lines.push(`- [${opp.category}] ${opp.description} (时间窗口: ${opp.time_window}) → ${opp.rationale}${relatedStr}`);
270	      }
271	    } else {
272	      lines.push('');
273	      lines.push('### 机会');
274	      lines.push('暂无显著机会。');
275	    }
276	
277	    // 整体风险评估
278	    lines.push('');
279	    lines.push(`**整体风险评估**: ${riskOpp.overall_risk_assessment || '暂无'}`);
280	
281	    return lines.join('\n');
282	  }
