42	function wrapSvg(content: string, w: number, h: number): string {
43	  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}">
44	  <style>
45	    .title { font-family: system-ui, -apple-system, sans-serif; font-size: 18px; font-weight: bold; fill: #111827; }
46	    .label { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #374151; }
47	    .value { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #6B7280; }
48	    .note { font-family: system-ui, -apple-system, sans-serif; font-size: 11px; fill: #9CA3AF; }
49	    .grid { stroke: #E5E7EB; stroke-width: 1; stroke-dasharray: 4 4; }
50	    .axis { stroke: #D1D5DB; stroke-width: 2; }
51	    .ref-text { font-family: system-ui, -apple-system, sans-serif; font-size: 10px; fill: #9CA3AF; }
52	  </style>
53	${content}
54	</svg>`;
55	}
