105	export class SvgGenerator {
106	  private readonly width: number;
107	  private readonly height: number;
108	  private readonly colorScheme: 'default' | 'colorblind';
109	
110	  constructor(options?: SvgOptions) {
111	    this.width = options?.width ?? 800;
