117	  // Topic bar chart
118	  // ---------------------------------------------------------------------------
119	
120	  generateTopicBarChart(
121	    topicFrequency: Record<string, number>,
122	    date: string,
123	    topN = 10,
124	  ): string {
125	    log.info(`Generating topic bar chart for ${date} (topN=${topN})`);
126	
127	    const entries = Object.entries(topicFrequency)
128	      .sort((a, b) => b[1] - a[1])
129	      .slice(0, Math.max(1, topN)); // At least try to show 1
130	
131	    if (entries.length === 0) {
132	      // Empty state
133	      return this.emptySvg(`AI 话题热度 — ${date}`, '暂无话题数据', date);
134	    }
135	
136	    const maxVal = entries[0][1];
137	    const w = this.width;
138	    const h = this.height;
139	
140	    const barH = 30;
141	    const barGap = 5;
142	    const barAreaTop = 70;
143	    const barAreaBottom = 430;
144	    const maxBars = Math.min(entries.length, Math.floor((barAreaBottom - barAreaTop) / (barH + barGap)));
145	    const limited = entries.slice(0, maxBars);
146	
147	    const labelX = 200;
148	    const barStartX = 210;
149	    const maxBarWidth = 440;
150	    const valueX = 660;
151	
152	    const bars: string[] = [];
153	    const gridLines: string[] = [];
154	    const labels: string[] = [];
155	    const values: string[] = [];
156	
157	    // Grid lines (0%, 25%, 50%, 75%, 100%)
158	    for (const pct of [0, 0.25, 0.5, 0.75, 1]) {
159	      const gx = barStartX + maxBarWidth * pct;
160	      gridLines.push(`  <line class="grid" x1="${gx.toFixed(1)}" y1="${barAreaTop - 10}" x2="${gx.toFixed(1)}" y2="${barAreaTop + limited.length * (barH + barGap)}" />`);
161	    }
162	
163	    limited.forEach(([topic, count], i) => {
164	      const y = barAreaTop + i * (barH + barGap);
165	      const barWidth = maxVal > 0 ? (count / maxVal) * maxBarWidth : 0;
166	
167	      const colorIndex = this.colorScheme === 'colorblind'
168	        ? i % BARS_COLORBLIND.length
169	        : i % BARS_DEFAULT.length;
170	      const color = this.colorScheme === 'colorblind'
171	        ? BARS_COLORBLIND[colorIndex]
172	        : (i < 1 ? BARS_DEFAULT[0] : BARS_DEFAULT[Math.min(colorIndex, BARS_DEFAULT.length - 1)]);
173	
174	      // If colorblind, add pattern
175	      let rectExtra = '';
176	      if (this.colorScheme === 'colorblind') {
177	        rectExtra = ` fill="url(#cbBar${i})"`;
178	        // Add pattern definition (will be hoisted)
179	      } else {
180	        rectExtra = ` fill="${color}"`;
181	      }
182	
183	      labels.push(`  <text class="label" x="${labelX}" y="${y + barH / 2 + 4}" text-anchor="end">${truncate(topic, 15)}</text>`);
184	      bars.push(`  <rect role="bar" x="${barStartX}" y="${y}" width="${barWidth.toFixed(1)}" height="${barH}" rx="4"${rectExtra} />`);
185	      values.push(`  <text class="value" x="${valueX}" y="${y + barH / 2 + 4}">${count}</text>`);
186	    });
187	
188	    // Add pattern defs for colorblind
189	    let defs = '';
190	    if (this.colorScheme === 'colorblind') {
191	      const patterns = limited.map((_, i) => {
192	        const colorIndex = i % BARS_COLORBLIND.length;
193	        const color = BARS_COLORBLIND[colorIndex];
194	        return `  <pattern id="cbBar${i}" patternUnits="userSpaceOnUse" width="8" height="8">
195	    <rect width="8" height="8" fill="${color}" />
196	    <rect x="${i % 2 * 4}" y="${i % 2 * 4}" width="4" height="4" fill="#ffffff" opacity="0.4" />
197	  </pattern>`;
198	      });
199	      defs = `<defs>\n${patterns.join('\n')}\n  </defs>\n`;
200	    }
201	
202	    const svgContent = [
203	      defs,
204	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">AI 话题热度 Top-${limited.length} — ${date}</text>`,
205	      gridLines.join('\n'),
206	      labels.join('\n'),
207	      bars.join('\n'),
208	      values.join('\n'),
209	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
210	    ].join('\n');
211	
212	    return wrapSvg(svgContent, w, h);
213	  }
